async def _sleep_chunked(seconds):
    """긴 대기를 0.5초 단위로 나눠 하트비트를 보내고 정지 버튼을 확인한다 (sleep(15)도 무응답으로 끊기지 않는다)."""
    remaining = max(0.0, float(seconds))
    while True:
        chunk = min(_HEARTBEAT_INTERVAL, remaining)
        await asyncio.sleep(chunk)
        remaining -= chunk
        if remaining <= 1e-9:
            return
        _raise_if_stopped()
        _raise_task_error()
        _heartbeat()

